/* ---------- 7 лет: 1 класс. Математика (Моро, «Математика, 1 класс») ---------- */
const M7_MATH = [
 { id:'m1_1', t:'Числа от 1 до 10. Состав числа', th:'Каждое число до 10 можно разложить на две части. 7 = 1 + 6 = 2 + 5 = 3 + 4.<br>Знать состав чисел — значит быстро считать в уме.',
   g: r => { const n = r.int(4, 10), a = r.int(1, n - 1); return NV(`${a} + ? = ${n}`, n - a, [n - a + 1, n - a - 1, n + a > 20 ? n : n + a].filter(x => x >= 0), `${n} = ${a} + ${n - a}.`); } },
 { id:'m1_2', t:'Сложение и вычитание в пределах 10', th:'Удобно прибавлять и вычитать по частям: 6 + 3 = 6 + 2 + 1 = 9.<br>Переставь числа, если так легче: 2 + 7 = 7 + 2 = 9.<br>Проверка вычитания сложением: 9 − 4 = 5, потому что 5 + 4 = 9.',
   g: r => { const a = r.int(1, 9), b = r.int(1, 10 - a); return r() < .5 ? N(`${a} + ${b} = ?`, a + b, `${a} + ${b} = ${a + b}`) : N(`${a + b} − ${b} = ?`, a, `${a} + ${b} = ${a + b}, значит ${a + b} − ${b} = ${a}`); } },
 { id:'m1_3', t:'На сколько больше, на сколько меньше', th:'Чтобы узнать, <b>на сколько</b> одно число больше другого, из большего вычитаем меньшее.<br>У Оли 7 конфет, у Пети 4. На сколько у Оли больше? 7 − 4 = <b>3</b>.',
   g: r => { const a = r.int(5, 10), b = r.int(1, a - 1); return NV(`У Оли ${cw(a, 'яблок')}, у Пети ${b}. На сколько у Оли больше?`, a - b, [a + b, a - b + 1, b], `${a} − ${b} = ${a - b}.`); } },
 { id:'m1_4', t:'Сантиметр. Отрезок', th:'Длину измеряем линейкой в <b>сантиметрах</b> (см).<br>Отрезок 5 см длиннее отрезка 3 см на 2 см.<br>Начинаем мерить от нуля на линейке, а не от края!',
   g: r => { const a = r.int(2, 9), b = r.int(1, a - 1); return MIX(
     () => NV(`Один отрезок ${a} см, другой ${b} см. На сколько первый длиннее?`, a - b, [a + b, a - b + 1, a], `${a} − ${b} = ${a - b} см.`),
     () => NV(`Карандаш длиной ${a} см сломали. Один кусок ${b} см. Какой длины другой?`, a - b, [a + b, b, a - b + 1], `${a} − ${b} = ${a - b} см.`),
     B(['От какого деления начинают мерить линейкой?|от нуля|от края линейки;от единицы;от середины']))(r); } },
 { id:'m1_5', t:'Числа от 11 до 20', th:'Число 14 — это <b>1 десяток и 4 единицы</b>. 10 + 4 = 14. 14 − 4 = 10. 14 − 10 = 4.<br>20 — это два десятка.',
   g: r => { const u = r.int(1, 9), t = r.int(0, 2);
     if (t === 0) return NV(`10 + ${u} = ?`, 10 + u, [u, 10 + u + 1, 100 + u], `Десяток и ${u} единиц — ${10 + u}.`);
     if (t === 1) return NV(`${10 + u} − ${u} = ?`, 10, [u, 10 + u, 11], `Убрали единицы — остался десяток.`);
     return NV(`Сколько единиц в числе ${10 + u}?`, u, [1, 10, u + 1], `${10 + u} = 1 дес. ${u} ед.`); } },
 { id:'m1_6', t:'Сложение с переходом через десяток', th:'Дополняем до 10, потом прибавляем остаток.<br>8 + 5 = 8 + 2 + 3 = 10 + 3 = <b>13</b>.<br>Помни состав чисел: чтобы из 8 получить 10, нужно 2.',
   g: r => { const a = r.int(5, 9), b = r.int(11 - a, 9); return NV(`${a} + ${b} = ?`, a + b, [a + b - 1, a + b + 1, a + b - 10], `${a} + ${10 - a} = 10, и ещё ${b - (10 - a)}: ${a + b}.`); } },
 { id:'m1_7', t:'Вычитание с переходом через десяток', th:'Сначала вычитаем до 10, потом остаток.<br>13 − 5 = 13 − 3 − 2 = 10 − 2 = <b>8</b>.',
   g: r => { const a = r.int(11, 18), b = r.int(a - 9, 9); if (b <= a % 10) return N('12 − 5 = ?', 7, '12 − 2 − 3 = 7'); return NV(`${a} − ${b} = ?`, a - b, [a - b + 1, a - b - 1, a - b + 10], `${a} − ${a % 10} = 10, 10 − ${b - a % 10} = ${a - b}.`); } },
 { id:'m1_8', t:'Задачи в одно действие', th:'В задаче есть <b>условие</b> (что известно) и <b>вопрос</b> (что найти).<br>Слова «стало больше», «ещё», «вместе» — подсказка к сложению; «осталось», «отдал», «улетели» — к вычитанию. Но всегда думай сам: подсказки иногда обманывают!',
   g: r => { const t = r.int(0, 3), a = r.int(3, 9), b = r.int(2, 8);
     if (t === 0) return NV(`На поле играли ${a} мальчиков. Пришли ещё ${b}. Сколько мальчиков стало на поле?`, a + b, [a + b + 1, Math.abs(a - b), a + b - 1], `${a} + ${b} = ${a + b}.`);
     if (t === 1) return NV(`В вазе было ${a + b} конфет. Дети съели ${b}. Сколько осталось?`, a, [a + b + b > 20 ? a + 1 : a + b + b, a - 1, b], `${a + b} − ${b} = ${a}.`);
     if (t === 2) return NV(`Когда Маша отдала подруге ${b} наклеек, у неё осталось ${a}. Сколько наклеек было сначала?`, a + b, [Math.abs(a - b), a, a + b + 1], `Подвох! «Отдала» — а решаем сложением: было ${a} + ${b} = ${a + b}.`);
     return NV(`У Вани ${a} машинок, а у Саши на ${b} больше. Сколько машинок у Саши?`, a + b, [Math.abs(a - b), a, b], `На ${b} больше: ${a} + ${b} = ${a + b}.`); } },
 { id:'m1_9', t:'Килограмм и литр', th:'Массу (сколько весит) измеряют в <b>килограммах</b> (кг) на весах.<br>Сколько жидкости — в <b>литрах</b> (л). Пакет молока — 1 л, ведро — около 10 л.',
   g: B(['Чем измеряют, сколько весит арбуз?|килограммами|литрами;сантиметрами;часами','В чём измеряют воду в ведре?|в литрах|в килограммах;в сантиметрах;в метрах','Арбуз весит 5 кг, дыня 2 кг. На сколько арбуз тяжелее?|на 3 кг|на 7 кг;на 2 кг;на 5 кг','В кастрюле 3 л супа, налили ещё 2 л. Сколько стало?|5 л|1 л;6 л;3 л','Что тяжелее: 1 кг пуха или 1 кг гвоздей?|одинаково|гвозди;пух|Оба весят 1 кг.']) },
 { id:'m1_10', t:'Десятки до 100', th:'10, 20, 30 … 100 — круглые числа. 30 — это 3 десятка.<br>40 + 20 = 4 дес. + 2 дес. = 6 дес. = <b>60</b>.',
   g: r => { const a = r.int(1, 8), b = r.int(1, 9 - a); return r() < .5 ? NV(`${a * 10} + ${b * 10} = ?`, (a + b) * 10, [a + b, (a + b + 1) * 10, (a + b) * 100], `${a} дес. + ${b} дес. = ${a + b} дес.`) : NV(`${(a + b) * 10} − ${b * 10} = ?`, a * 10, [a, (a + 1) * 10, (a - 1) * 10].filter(x => x >= 0), `${a + b} дес. − ${b} дес. = ${a} дес.`); } }
];

